using System;

class Box { public int N; }

class Program
{
    static void Main()
    {
        int a = 5;
        int b = a;            // value type: b is an independent copy
        b = 99;
        Console.WriteLine("a=" + a + " b=" + b);

        Box x = new Box { N = 5 };
        Box y = x;            // reference type: y points to the SAME object
        y.N = 99;
        Console.WriteLine("x.N=" + x.N + " y.N=" + y.N);

        int? maybe = null;    // a value type needs ? to hold null
        Console.WriteLine("maybe has value: " + maybe.HasValue);

        string s = "hi";
        string t = s;
        t += "!";             // strings are immutable: t gets a NEW string
        Console.WriteLine("s=" + s + " t=" + t);
        Console.WriteLine("== compares contents: " + (new string('a', 3) == "aaa"));
    }
}

using System;

class Program
{
    static void Main()
    {
        double d = 0;
        decimal m = 0;
        for (int i = 0; i < 10; i++)
        {
            d += 0.1;     // 0.1 is not exactly representable in binary
            m += 0.1m;    // decimal stores digits and a power-of-ten scale
        }
        Console.WriteLine("double sum  == 1.0 ? " + (d == 1.0) + "  (" + d.ToString("R") + ")");
        Console.WriteLine("decimal sum == 1.0 ? " + (m == 1.0m) + "  (" + m + ")");

        // Cost: decimal is 16 bytes and slower; time a loop of each
        var sw = System.Diagnostics.Stopwatch.StartNew();
        double x = 0; for (int i = 0; i < 5000000; i++) x += i * 0.5;
        long t1 = sw.ElapsedTicks; sw.Restart();
        decimal y = 0; for (int i = 0; i < 5000000; i++) y += i * 0.5m;
        long t2 = sw.ElapsedTicks;
        Console.WriteLine("decimal slower than double: " + (t2 > t1));
        Console.WriteLine("sizes: double=8 bytes, decimal=" + sizeof(decimal) + " bytes");
    }
}

using System;

class Program
{
    static void Main()
    {
        int max = int.MaxValue;
        Console.WriteLine("max = " + max);

        int wrapped = unchecked(max + 1);     // default behaviour: wraps silently
        Console.WriteLine("unchecked max+1 = " + wrapped);

        try
        {
            int boom = checked(max + 1);      // checked: throws instead of wrapping
            Console.WriteLine(boom);
        }
        catch (OverflowException)
        {
            Console.WriteLine("checked max+1 -> OverflowException");
        }

        try
        {
            Console.WriteLine(Math.Abs(int.MinValue));  // throws even when unchecked
        }
        catch (OverflowException)
        {
            Console.WriteLine("Math.Abs(int.MinValue) -> OverflowException");
        }

        // Hashing is a good use for unchecked: wrap-around is wanted
        int h = 17;
        foreach (char c in "hello") h = unchecked(h * 31 + c);
        Console.WriteLine("hash(hello) = " + h);
    }
}

using System;
using System.Collections.Generic;

class Config
{
    public const int DaysInWeek = 7;                         // compile-time, copied into callers
    public static readonly DateTime Started = DateTime.Now;  // one per type, set at run time
    public readonly int Id;                                  // one per instance, set in ctor
    public readonly List<string> Tags = new List<string>();  // readonly is shallow

    public Config(int id) { Id = id; }
}

class Program
{
    static void Main()
    {
        Config a = new Config(1);
        Config b = new Config(2);
        Console.WriteLine("const: " + Config.DaysInWeek);
        Console.WriteLine("ids: " + a.Id + ", " + b.Id);
        Console.WriteLine("same static for both: " + (Config.Started == Config.Started));

        // a.Id = 5;   // compile error: cannot assign a readonly field
        a.Tags.Add("mutated");   // allowed: the reference is fixed, the list is not
        Console.WriteLine("readonly list now has " + a.Tags.Count + " item(s)");
    }
}

using System;
using System.Collections.Generic;

class Program
{
    static void Main()
    {
        var n = 42;                       // compiler infers int
        var price = 19.99;                // infers double
        var money = 19.99m;               // infers decimal
        var list = new List<string>();    // type is obvious: good use of var
        var anon = new { Name = "Ada", Age = 36 };  // unspeakable type: var is required

        Console.WriteLine(n.GetType().Name + " " + price.GetType().Name + " " + money.GetType().Name);
        Console.WriteLine(list.GetType().Name + " " + anon.Name + " " + anon.Age);

        // n = "text";   // compile error: var is fixed once inferred

        dynamic d = 42;                   // dynamic: binding happens at run time
        d = "now a string";
        Console.WriteLine("dynamic holds: " + d.GetType().Name + " / " + d.Length);
    }
}

using System;
using System.Globalization;

class Program
{
    static void Main()
    {
        CultureInfo de = new CultureInfo("de-DE");
        CultureInfo inv = CultureInfo.InvariantCulture;
        double x = 1234.5;

        Console.WriteLine("de-DE format:    " + x.ToString(de));     // 1234,5
        Console.WriteLine("invariant format:" + " " + x.ToString(inv)); // 1234.5

        // Parsing "1.5": under de-DE the dot is a thousands separator
        double bad = double.Parse("1.5", de);
        double good = double.Parse("1.5", inv);
        Console.WriteLine("Parse(\"1.5\") with de-DE     = " + bad);
        Console.WriteLine("Parse(\"1.5\") with invariant = " + good.ToString(inv));

        // Rule: machine-readable data (files, JSON, logs) always uses InvariantCulture
        double ok;
        bool parsed = double.TryParse("1,5", NumberStyles.Float, inv, out ok);
        Console.WriteLine("TryParse(\"1,5\", invariant) worked: " + parsed);
    }
}

using System;
using System.IO;
using System.Text;

class Program
{
    // Reads all non-negative/negative ints from a stream using a manual byte parser.
    static int[] ReadInts(Stream s, int count)
    {
        byte[] buf = new byte[1 << 16];      // read 64 KB chunks
        int[] res = new int[count];
        int n = 0, len = 0, pos = 0;
        while (n < count)
        {
            int v = 0; bool neg = false, any = false;
            while (true)
            {
                if (pos == len) { len = s.Read(buf, 0, buf.Length); pos = 0; if (len <= 0) break; }
                byte b = buf[pos++];
                if (b == '-') { neg = true; any = true; }
                else if (b > ' ') { v = v * 10 + (b - '0'); any = true; }   // digit
                else if (any) break;                                         // whitespace ends a token
            }
            if (!any) break;
            res[n++] = neg ? -v : v;
        }
        return res;
    }

    static void Main()
    {
        string text = "3 -14 15\r\n92 -6\r\n";   // CRLF is just whitespace here
        Console.WriteLine("input: " + text.Replace("\r\n", "\\r\\n"));
        Stream s = new MemoryStream(Encoding.ASCII.GetBytes(text));
        int[] a = ReadInts(s, 5);
        StringBuilder sb = new StringBuilder();   // build output, write once
        long sum = 0;
        foreach (int x in a) { sb.Append(x).Append(' '); sum += x; }
        sb.Append("| sum=").Append(sum);
        Console.WriteLine(sb.ToString());         // O(total bytes), one buffer, no Split
    }
}

using System;

class Program
{
    static void Main()
    {
        Console.WriteLine("(int)3.7   = " + (int)3.7);      // truncates toward zero
        Console.WriteLine("(int)-3.7  = " + (int)-3.7);
        Console.WriteLine("Floor(-3.7)= " + Math.Floor(-3.7));

        // Half-to-even ("banker's") rounding is the default
        Console.WriteLine("Convert.ToInt32(2.5) = " + Convert.ToInt32(2.5));
        Console.WriteLine("Math.Round(2.5m) = " + Math.Round(2.5m));
        Console.WriteLine("Math.Round(3.5m) = " + Math.Round(3.5m));

        // School rounding must be asked for explicitly
        Console.WriteLine("AwayFromZero(2.5m) = " + Math.Round(2.5m, MidpointRounding.AwayFromZero));

        // decimal keeps 2.675 exact, so it is a true midpoint: 2.68 (even digit 8)
        Console.WriteLine("Round(2.675m, 2) = " + Math.Round(2.675m, 2));
    }
}

using System;

class Program
{
    // True if a * b would overflow int. Uses only division and comparisons.
    static bool MulOverflows(int a, int b)
    {
        if (a == 0 || b == 0) return false;
        if (a > 0 && b > 0) return a > int.MaxValue / b;
        if (a < 0 && b < 0) return a < int.MaxValue / b;   // product is positive
        if (a > 0) return b < int.MinValue / a;            // a > 0, b < 0
        return a < int.MinValue / b;                       // a < 0, b > 0
    }

    static void Main()
    {
        int[][] tests = {
            new int[] { 46340, 46340 }, new int[] { 46341, 46341 },
            new int[] { -46341, 46341 }, new int[] { -46341, -46341 },
            new int[] { int.MinValue, -1 }, new int[] { 0, int.MaxValue }
        };
        foreach (int[] t in tests)
        {
            bool mine = MulOverflows(t[0], t[1]);
            bool truth = (long)t[0] * t[1] > int.MaxValue || (long)t[0] * t[1] < int.MinValue;
            Console.WriteLine(t[0] + " * " + t[1] + " overflows: " + mine + " (long check: " + truth + ")");
        }
    }
}
